mapper.select:
SELECT id, valid_from, valid_to, valid_to_precision FROM facts
 WHERE kb_id = #{kbId} AND subject_id = #{subjectId} AND predicate_id = #{predicateId} AND object_id = #{objectId}
   AND invalidated_at IS NULL

SELECT id, valid_from, valid_to, valid_to_precision FROM facts
 WHERE kb_id = #{kbId} AND subject_id = #{subjectId} AND predicate_id = #{predicateId} AND object_value = #{objectValue,typeHandler=tech.seexun.jknow.store.typehandler.JsonNodeTypeHandler}
   AND object_id IS NULL AND invalidated_at IS NULL

SELECT id FROM facts
 WHERE layer = 'open' AND kb_id = #{kbId} AND subject_id = #{subjectId} AND phrase = #{phrase}
   AND object_value = #{objectValue,typeHandler=tech.seexun.jknow.store.typehandler.JsonNodeTypeHandler}
   AND object_id IS NULL AND invalidated_at IS NULL
 ORDER BY recorded_at LIMIT 1

mapper.update:
UPDATE facts
   SET attested_from = #{at}, attested_by = #{by}
 WHERE id = #{factId} AND layer = 'open' AND invalidated_at IS NULL
   AND (attested_from IS NULL OR attested_from > #{at}
        OR (attested_from = #{at} AND attested_by IS DISTINCT FROM #{by}))

UPDATE fact_evidence SET attested_at = #{at}, attested_by = #{by}
 WHERE fact_id = #{factId} AND chunk_id = #{chunkId}
   AND (attested_at IS DISTINCT FROM #{at} OR attested_by IS DISTINCT FROM #{by})
